    # (Avoid infinite failure; still deterministic.)
    if unassigned:
        # attempt greedy packing of remaining into existing routes if feasible, else new singletons
        route_of = {}
        for rid, rt in enumerate(routes):
            for u in rt:
                route_of[u] = rid

        rem = sorted([u for u in customers if u in unassigned])
        for u in rem:
            placed = False
            # best insertion across existing routes by delta cost at best position (scan end positions and nearest)
            best_r = None
            best_pos = None
            best_delta = None
            for r in range(len(routes)):
                if route_caps[r] + demands[u] > cap:
                    continue
                rt = routes[r]
                m = len(rt)
                # try positions: 0, end, and a few neighborhood positions based on proximity to depot (simple deterministic)
                positions = [0, m]
                # also try positions adjacent to closest node by distance to u
                if m > 0:
                    # choose up to 3 closest nodes in the route to u for insertion positions
                    # deterministic scan
                    best_close = []
                    for i in range(m):
                        v = rt[i]
                        dv = d(u, v)
                        inserted = False
                        for t in range(len(best_close)):
                            if dv < best_close[t][0]:
                                best_close.insert(t, (dv, i))
                                inserted = True
                                break
                        if not inserted and len(best_close) < 3:
                            best_close.append((dv, i))
                        if len(best_close) > 3:
                            best_close.pop()
                    for _, i in best_close:
                        positions.append(i)
                        if i + 1 <= m:
                            positions.append(i + 1)
                # unique positions
                used_pos = set()
                for pos in positions:
                    if pos < 0 or pos > m or pos in used_pos:
                        continue
                    used_pos.add(pos)
                    delta = route_cost_delta_insert(rt, pos, u)
                    if best_delta is None or delta < best_delta or (delta == best_delta and (r, pos) < (best_r, best_pos)):
                        best_delta = delta
                        best_r = r
                        best_pos = pos
            if best_r is not None:
                routes[best_r].insert(best_pos, u)
                route_caps[best_r] += demands[u]
                placed = True
            if not placed:
                routes.append([u])
                route_caps.append(demands[u])

        unassigned.clear()

    # --- Repair: ensure all customers appear exactly once ---
    # If duplicates somehow exist, keep first occurrence deterministically.
    seen = set()
    cleaned_routes = []
    new_caps = []
    for rt in routes:
        nrt = []
        cap_used = 0
        for u in rt:
            if u in seen:
                continue
            nrt.append(u)
            seen.add(u)
            cap_used += demands[u]
        if nrt:
            cleaned_routes.append(nrt)
            new_caps.append(cap_used)
    routes = cleaned_routes
    route_caps = new_caps

    # Add missing customers deterministically as singleton routes (feasibility assumed).
    if len(seen) < n:
        for u in customers:
            if u not in seen:
                routes.append([u])
                route_caps.append(demands[u])
                seen.add(u)

    # --- Local search: intra-route 2-opt ---
    def two_opt(rt):
        m = len(rt)
        if m < 4:
            return rt, False
        improved = False
        max_pass = 1 if m > 60 else 2
        for _ in range(max_pass):
            best_gain = 0.0
            best_i = best_j = None
            base_cost = route_cost(rt)
            for i in range(m - 3):
                a = rt[i]
                b = rt[i + 1]
                for j in range(i + 2, m - 1):
                    c = rt[j]
                    e = rt[j + 1]
                    old = d(a, b) + d(c, e)
                    new = d(a, c) + d(b, e)
                    gain = old - new
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best_i, best_j = i, j
            if best_i is None:
                break
            i, j = best_i, best_j
            # reverse segment (i+1..j)
            rt = rt[:i + 1] + list(reversed(rt[i + 1:j + 1])) + rt[j + 1:]
            improved = True
        return rt, improved

    for rid in range(len(routes)):
        rt2, _ = two_opt(routes[rid])
        routes[rid] = rt2
        route_caps[rid] = route_demand(rt2)

